ga5s(){return"\u0625\u0636\u0627\u0641\u0629 \u0645\u0644\u062e\u0635 \u0625\u0644\u0649 \u0642\u0627\u0626\u0645\u0629 \u062d\u0627\u0644\u0627\u062a \u0627\u0644\u0637\u0628\u064a\u0628 \u0627\u0644\u0645\u0637\u0628\u0648\u0639\u0629: \u063a\u064a\u0631 \u0627\u0644\u0645\u062f\u0641\u0648\u0639 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0643\u0634\u0641\u060c \u0627\u0644\u0631\u0635\u064a\u062f \u0627\u0644\u0627\u0641\u062a\u062a\u0627\u062d\u064a \u0645\u0639 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u0623\u062e\u0631\u0649\u060c \u0648\u0625\u062c\u0645\u0627\u0644\u064a \u0645\u0627 \u064a\u062f\u064a\u0646 \u0628\u0647 \u0627\u0644\u0637\u0628\u064a\u0628."},
ga47(){return"\u062f\u0645\u062c \u0639\u064a\u0627\u062f\u0627\u062a \u0627\u0644\u0637\u0628\u064a\u0628 \u0627\u0644\u0648\u0627\u062d\u062f \u0641\u064a \u0627\u0644\u0645\u0633\u062a\u0646\u062f\u0627\u062a"},
ga46(){return"\u0641\u064a \u0641\u0627\u062a\u0648\u0631\u0629 \u0627\u0633\u062a\u0644\u0627\u0645 \u0627\u0644\u0637\u0628\u064a\u0628 \u0623\u0648 \u0625\u064a\u0635\u0627\u0644 \u0627\u0644\u062f\u0641\u0639\u060c \u062a\u062e\u0637\u064a \u0637\u0628\u0627\u0639\u0629 \u0633\u0637\u0631 \u0645\u0646\u0641\u0635\u0644 \u0644\u0644\u0639\u064a\u0627\u062f\u0629/\u0627\u0644\u0637\u0628\u064a\u0628 \u0639\u0646\u062f\u0645\u0627 \u062a\u062d\u062a\u0648\u064a \u0627\u0644\u0639\u064a\u0627\u062f\u0629 \u0639\u0644\u0649 \u0637\u0628\u064a\u0628 \u0648\u0627\u062d\u062f \u0641\u0642\u0637 \u0646\u0634\u0637."},
