ga5c(){return"\u0639\u0646\u062f \u0627\u0644\u0625\u064a\u0642\u0627\u0641\u060c \u062a\u064f\u0639\u0631\u0636 \u0628\u0627\u0644\u062f\u064a\u0646\u0627\u0631 \u0628\u062f\u0644\u0627\u064b \u0645\u0646 \u0630\u0644\u0643. \u062a\u062d\u062a\u0641\u0638 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u062d\u0627\u0644\u064a\u0629 \u0628\u0633\u0639\u0631 \u0627\u0644\u0635\u0631\u0641 \u0627\u0644\u062e\u0627\u0635 \u0628\u0647\u0627 \u0641\u064a \u0643\u0644\u062a\u0627 \u0627\u0644\u062d\u0627\u0644\u062a\u064a\u0646."},
ga44(){return"\u0628\u0648\u0627\u0628\u0629 \u0627\u0644\u0639\u064a\u0627\u062f\u0629 \u0645\u0641\u0639\u0651\u0644\u0629"},
ga45(){return"\u0623\u0648\u0642\u0641 \u0647\u0630\u0627 \u0627\u0644\u062e\u064a\u0627\u0631 \u0625\u0630\u0627 \u0643\u0627\u0646 \u0647\u0630\u0627 \u0627\u0644\u0645\u062e\u062a\u0628\u0631 \u0644\u0627 \u064a\u0633\u062a\u062e\u062f\u0645 \u062a\u0637\u0628\u064a\u0642 \u0628\u0648\u0627\u0628\u0629 \u0627\u0644\u0637\u0628\u064a\u0628/\u0627\u0644\u0639\u064a\u0627\u062f\u0629 \u0627\u0644\u0645\u0646\u0641\u0635\u0644 \u2014 \u064a\u062e\u0641\u064a \u062c\u0631\u0633 \u0627\u0644\u0625\u0634\u0639\u0627\u0631\u0627\u062a \u0648\u0627\u0644\u0645\u0631\u0627\u0633\u0644\u0629."},
ga5w(){return"\u062d\u0630\u0641 \u0627\u0644\u0645\u0644\u0641\u0627\u062a \u0645\u0646 \u0627\u0644\u062a\u062e\u0632\u064a\u0646 \u0628\u0639\u062f \u0645\u0634\u0627\u0647\u062f\u062a\u0647\u0627 \u0645\u0646 \u0627\u0644\u0637\u0631\u0641\u064a\u0646"},
ga5x(){return"\u064a\u062a\u0645 \u0627\u0644\u0627\u062d\u062a\u0641\u0627\u0638 \u0628\u0633\u062c\u0644\u0627\u062a \u0627\u0644\u0645\u0631\u0641\u0642\u0627\u062a \u0644\u0623\u063a\u0631\u0627\u0636 \u0627\u0644\u062a\u062f\u0642\u064a\u0642\u061b \u064a\u064f\u062d\u0630\u0641 \u0645\u062d\u062a\u0648\u0649 \u0627\u0644\u0645\u0644\u0641 \u0627\u0644\u0623\u0633\u0627\u0633\u064a \u0641\u0642\u0637."},
ga5k(){return"\u0645\u064f\u062f\u0631\u064e\u062c \u0644\u0627\u062a\u0635\u0627\u0644\u0627\u062a \u0627\u0644\u0639\u064a\u0627\u062f\u0627\u062a"},
ga5l(){return"\u0639\u0646\u062f \u0627\u0644\u0625\u064a\u0642\u0627\u0641\u060c \u0644\u0646 \u064a\u0638\u0647\u0631 \u0647\u0630\u0627 \u0627\u0644\u0645\u062e\u062a\u0628\u0631 \u0639\u0646\u062f\u0645\u0627 \u062a\u0628\u062d\u062b \u0639\u064a\u0627\u062f\u0629 \u0639\u0646 \u0645\u062e\u062a\u0628\u0631 \u0644\u0644\u0627\u062a\u0635\u0627\u0644 \u0628\u0647\u060c \u0648\u0644\u0646 \u064a\u0642\u0628\u0644 \u062a\u0633\u062c\u064a\u0644\u0627\u062a \u0630\u0627\u062a\u064a\u0629 \u062c\u062f\u064a\u062f\u0629 \u0644\u0644\u0623\u0637\u0628\u0627\u0621 \u0623\u0648 \u0627\u0644\u0639\u064a\u0627\u062f\u0627\u062a."},
ga4x(){return"\u0625\u062e\u0641\u0627\u0621 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u0645\u0644\u063a\u0627\u0629 \u0645\u0646 \u0644\u0648\u062d\u0629 \u0627\u0644\u062d\u0627\u0644\u0627\u062a"},
ga4y(){return"\u0639\u0646\u062f \u0627\u0644\u062a\u0641\u0639\u064a\u0644\u060c \u0644\u0627 \u062a\u0638\u0647\u0631 \u0627\u0644\u062d\u0627\u0644\u0629 \u0627\u0644\u0645\u0644\u063a\u0627\u0629 \u0641\u064a \u0644\u0648\u062d\u0629 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0625\u0637\u0644\u0627\u0642\u064b\u0627 \u0628\u062f\u0644\u0627\u064b \u0645\u0646 \u0638\u0647\u0648\u0631\u0647\u0627 \u0628\u0627\u0647\u062a\u0629 \u0641\u064a \u0639\u0645\u0648\u062f \u0645\u0631\u062d\u0644\u062a\u0647\u0627. \u062a\u0628\u0642\u0649 \u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u0628\u062d\u062b \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0641\u064a \u0643\u0644 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0639\u0644\u0649 \u0623\u064a \u062d\u0627\u0644."},
ga4D(){return"\u0623\u062f\u062e\u0644 \u0639\u062f\u062f \u0623\u064a\u0627\u0645 \u0635\u062d\u064a\u062d (\u0623\u0643\u0628\u0631 \u0645\u0646 0)."},
ga5K(){return"\u062a\u062a\u0628\u0639 \u0632\u064a\u0627\u0631\u0627\u062a \u0627\u0644\u0645\u0646\u062f\u0648\u0628"},
ga5L(){return'\u0643\u0645 \u0639\u062f\u062f \u0627\u0644\u0623\u064a\u0627\u0645 \u0627\u0644\u062a\u064a \u064a\u062c\u0628 \u0623\u0646 \u062a\u0645\u0631 \u0645\u0646\u0630 \u0622\u062e\u0631 \u0632\u064a\u0627\u0631\u0629 \u0644\u0644\u0645\u0646\u062f\u0648\u0628 \u0644\u0637\u0628\u064a\u0628 \u0642\u0628\u0644 \u0623\u0646 \u064a\u064f\u0639\u0644\u064e\u0651\u0645 \u0647\u0630\u0627 \u0627\u0644\u0637\u0628\u064a\u0628 "\u0645\u0633\u062a\u062d\u0642" \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0641\u064a \u062a\u0628\u0648\u064a\u0628 \u0627\u0644\u0632\u064a\u0627\u0631\u0627\u062a.'},
