alp(a){return"\u0627\u0644\u0623\u0633\u0639\u0627\u0631 \u2014 "+a},
galo(){return"\u0627\u062a\u0631\u0643 \u0627\u0644\u062d\u0642\u0644 \u0641\u0627\u0631\u063a\u064b\u0627 \u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0633\u0639\u0631 \u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a \u0644\u0644\u0645\u0627\u062f\u0629. \u0627\u0644\u0642\u064a\u0645\u0629 \u0627\u0644\u0645\u062d\u0641\u0648\u0638\u0629 \u062a\u062e\u0635 \u0647\u0630\u0627 \u0627\u0644\u0637\u0628\u064a\u0628 \u0641\u0642\u0637."},
