gamx(){return"\u0647\u0630\u0627 \u0627\u0644\u0645\u0648\u0638\u0641 \u064a\u064f\u062d\u0627\u0633\u0628 \u0628\u0627\u0644\u0646\u0633\u0628\u0629\u060c \u0644\u0630\u0627 \u0627\u0644\u0645\u0628\u0644\u063a \u0644\u0643\u0644 \u0648\u062d\u062f\u0629 \u0647\u0646\u0627 \u0644\u0627 \u064a\u064f\u0637\u0628\u064e\u0651\u0642 - \u0627\u0633\u062a\u062e\u062f\u0645 \u0646\u0633\u0628\u0629 (\u0645\u062b\u0644\u0627\u064b 60%)."},
gWE(){return"\u0645\u062b\u0644\u0627\u064b 2000 \u0623\u0648 60%"},
gamr(){return"\u0644\u0643\u0644 \u0641\u0643"},
gamw(){return"\u0627\u0643\u062a\u0628 \u0645\u0628\u0644\u063a\u0627\u064b \u0623\u0648 \u0646\u0633\u0628\u0629"},
gamN(){return"\u062d\u0633\u0628 \u0627\u0644\u0637\u0628\u064a\u0628"},
gamM(){return"\u0642\u0627\u0639\u062f\u0629 \u0627\u0644\u0637\u0628\u064a\u0628 \u062a\u064f\u0637\u0628\u064e\u0651\u0642 \u0639\u0644\u0649 \u062d\u0627\u0644\u0627\u062a \u0630\u0644\u0643 \u0627\u0644\u0637\u0628\u064a\u0628 \u0648\u0644\u0647\u0627 \u0627\u0644\u0623\u0648\u0644\u0648\u064a\u0629 \u0639\u0644\u0649 \u0623\u0633\u0639\u0627\u0631 \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644."},
