gamY(){return"\u0646\u0633\u0628\u0629 \u0645\u0646 \u0627\u0644\u0645\u0628\u0627\u0644\u063a \u0627\u0644\u0648\u0627\u0635\u0644\u0629 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)"},
gamX(){return"\u062a\u064f\u0636\u0627\u0641 \u0647\u0630\u0647 \u0627\u0644\u0646\u0633\u0628\u0629 \u0645\u0646 \u0643\u0644 \u0645\u0628\u0644\u063a \u064a\u0635\u0644 \u0645\u0646 \u0627\u0644\u0623\u0637\u0628\u0627\u0621 \u062e\u0644\u0627\u0644 \u0641\u062a\u0631\u0629 \u0631\u0627\u062a\u0628 \u0627\u0644\u0645\u0648\u0638\u0641 \u0625\u0644\u0649 \u0639\u0645\u0648\u0644\u062a\u0647. \u0627\u062a\u0631\u0643\u0647 \u0641\u0627\u0631\u063a\u0627\u064b \u0628\u062f\u0648\u0646."},
