gahR(){return"\u0646\u0642\u0644 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645"},
gahQ(){return"\u0646\u0642\u0644 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641"},
gahP(){return"\u0646\u0642\u0644 \u0644\u0644\u0623\u0639\u0644\u0649 (\u064a\u0638\u0647\u0631 \u0623\u0648\u0644\u0627\u064b \u0641\u064a \u0625\u062f\u062e\u0627\u0644 \u0627\u0644\u062d\u0627\u0644\u0629)"},
gahO(){return"\u0646\u0642\u0644 \u0644\u0644\u0623\u0633\u0641\u0644"},
