gakM(){return"\u062f\u0627\u0648\u0627\u06a9\u0627\u0631\u06cc\u06cc\u06d5 \u0686\u0627\u0648\u06d5\u0695\u0648\u0627\u0646\u06d5\u06a9\u0627\u0646"},
