als(a){return"\u0646\u0648\u06ce\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc "+a+" \u06a9\u06d5\u06cc\u0633"},
alu(a){return"\u0646\u0631\u062e\u06cc "+a+" \u06a9\u06d5\u06cc\u0633 \u0646\u0648\u06ce\u06a9\u0631\u0627\u06cc\u06d5\u0648\u06d5"},
