gamv(){return"\u062e\u0627\u0646\u06d5\u06a9\u06d5 \u0628\u06d5\u062a\u0627\u06b5 \u0628\u0647\u06ce\u06b5\u06d5 \u0628\u06c6 \u0628\u06d5\u06a9\u0627\u0631\u0647\u06ce\u0646\u0627\u0646\u06cc \u0646\u0631\u062e\u06cc \u0626\u0627\u0633\u0627\u06cc\u06cc \u0626\u06d5\u0645 \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u06d5. \u0628\u0695\u06ce\u06a9 \u0628\u06c6 \u0647\u06d5\u0631 \u06cc\u06d5\u06a9\u06d5\u06cc\u06d5\u06a9 (\u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5 2000) \u06cc\u0627\u0646 \u0695\u06ce\u0698\u06d5\u06cc\u06d5\u06a9 \u0644\u06d5 \u0646\u0631\u062e\u06cc \u06a9\u06d5\u06cc\u0633 (\u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5 60%) \u0628\u0646\u0648\u0648\u0633\u06d5 \u062a\u06d5\u0646\u0647\u0627 \u0628\u06c6 \u0626\u06d5\u0645 \u062c\u06c6\u0631\u06d5."},
gamx(){return"\u0626\u06d5\u0645 \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u06d5 \u0628\u06d5 \u0695\u06ce\u0698\u06d5 \u062d\u06cc\u0633\u0627\u0628 \u062f\u06d5\u06a9\u0631\u06ce\u062a\u060c \u0628\u06c6\u06cc\u06d5 \u0628\u0695 \u0628\u06c6 \u0647\u06d5\u0631 \u06cc\u06d5\u06a9\u06d5\u06cc\u06d5\u06a9 \u0644\u06ce\u0631\u06d5 \u062c\u06ce\u0628\u06d5\u062c\u06ce \u0646\u0627\u0628\u06ce\u062a - \u0695\u06ce\u0698\u06d5 \u0628\u06d5\u06a9\u0627\u0631\u0628\u0647\u06ce\u0646\u06d5 (\u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5 60%)."},
gWE(){return"\u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5 2000 \u06cc\u0627\u0646 60%"},
gamr(){return"\u0628\u06c6 \u0647\u06d5\u0631 \u0634\u06d5\u0648\u06cc\u0644\u06af\u06d5\u06cc\u06d5\u06a9"},
gamw(){return"\u0628\u0695\u06ce\u06a9 \u06cc\u0627\u0646 \u0695\u06ce\u0698\u06d5\u06cc\u06d5\u06a9 \u0628\u0646\u0648\u0648\u0633\u06d5"},
gamN(){return"\u0628\u06d5\u067e\u06ce\u06cc \u062f\u06a9\u062a\u06c6\u0631"},
gamM(){return"\u06cc\u0627\u0633\u0627\u06cc \u062f\u06a9\u062a\u06c6\u0631 \u0644\u06d5\u0633\u06d5\u0631 \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627\u0646\u06cc \u0626\u06d5\u0648 \u062f\u06a9\u062a\u06c6\u0631\u06d5 \u062c\u06ce\u0628\u06d5\u062c\u06ce \u062f\u06d5\u0628\u06ce\u062a \u0648 \u0644\u06d5 \u0646\u0631\u062e\u06cc \u062c\u06c6\u0631\u06cc \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627\u0646\u06cc \u062e\u0648\u0627\u0631\u06d5\u0648\u06d5 \u0644\u06d5 \u067e\u06ce\u0634\u062a\u0631\u06d5."},
gamL(){return"\u0647\u06cc\u0686 \u06cc\u0627\u0633\u0627\u06cc\u06d5\u06a9\u06cc \u062f\u06a9\u062a\u06c6\u0631 \u0646\u06cc\u06cc\u06d5."},
gamK(){return"\u0632\u06cc\u0627\u062f\u06a9\u0631\u062f\u0646\u06cc \u06cc\u0627\u0633\u0627\u06cc \u062f\u06a9\u062a\u06c6\u0631"},
gamB(){return"\u06cc\u0627\u0633\u0627\u06cc \u062f\u06a9\u062a\u06c6\u0631"},
gamC(){return"\u062f\u06a9\u062a\u06c6\u0631"},
gamJ(){return"\u062c\u06c6\u0631\u06cc \u06a9\u06d5\u06cc\u0633"},
gWF(){return"\u0647\u06d5\u0645\u0648\u0648 \u062c\u06c6\u0631\u06d5\u06a9\u0627\u0646"},
