gamE(){return"\u0628\u06ce \u0633\u0646\u0648\u0648\u0631 \u0628\u06c6 \u0698\u0645\u0627\u0631\u06d5\u06cc \u06cc\u06d5\u06a9\u06d5\u06a9\u0627\u0646\u06cc \u06a9\u06d5\u06cc\u0633"},
gamz(){return"\u0628\u0695\u06cc \u0632\u06cc\u0627\u062f\u06d5 \u0628\u06c6 \u0647\u06d5\u0631 \u062f\u0627\u0648\u0627\u06a9\u0627\u0631\u06cc\u06cc\u06d5\u06a9 (\u0626\u0627\u0631\u06d5\u0632\u0648\u0648\u0645\u06d5\u0646\u062f\u0627\u0646\u06d5)"},
gamA(){return"...\u0626\u06d5\u06af\u06d5\u0631 \u062f\u0627\u0648\u0627\u06a9\u0627\u0631\u06cc\u06cc\u06d5\u06a9\u06d5 \u0632\u06cc\u0627\u062a\u0631 \u0628\u06ce\u062a \u0644\u06d5 (\u06cc\u06d5\u06a9\u06d5)"},
gamH(){return"\u0628\u06ce \u0633\u0646\u0648\u0648\u0631\u06cc \u06cc\u06d5\u06a9\u06d5"},
