ganE(){return"\u0648\u0634\u06d5 \u0646\u0647\u06ce\u0646\u06cc\u06cc\u06d5\u06a9\u0627\u0646 \u0648\u06d5\u06a9 \u06cc\u06d5\u06a9 \u0646\u06cc\u0646"},
ganH(){return"\u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc \u062f\u06d5\u0628\u06ce\u062a \u0644\u0627\u0646\u06cc\u06a9\u06d5\u0645 \u0666 \u067e\u06cc\u062a \u0628\u06ce\u062a"},
