anC(a){return"\u06af\u06c6\u0695\u06cc\u0646\u06cc \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc \u0633\u06d5\u0631\u06a9\u06d5\u0648\u062a\u0648\u0648 \u0646\u06d5\u0628\u0648\u0648: "+a},
gajh(){return"\u0647\u06d5\u0698\u0645\u0627\u0631\u06cc \u0686\u0648\u0648\u0646\u06d5\u0698\u0648\u0648\u0631\u06d5\u0648\u06d5\u06cc \u067e\u06c6\u0631\u062a\u0627\u0644"},
gaji(){return"\u0626\u0627\u0631\u06d5\u0632\u0648\u0648\u0645\u06d5\u0646\u062f\u0627\u0646\u06d5\u06cc\u06d5 \u2014 \u0626\u06d5\u0645 \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06d5 \u0647\u06ce\u0634\u062a\u0627 \u0647\u06cc\u0686 \u062f\u06a9\u062a\u06c6\u0631\u06ce\u06a9\u06cc \u067e\u06c6\u0631\u062a\u0627\u06b5\u06cc \u0646\u06cc\u06cc\u06d5. \u0628\u06d5\u062a\u0627\u06b5\u06cc \u0628\u0647\u06ce\u06b5\u06d5\u0648\u06d5 \u0628\u06c6 \u0632\u06cc\u0627\u062f\u06a9\u0631\u062f\u0646\u06cc \u0626\u06d5\u0645 \u062f\u06a9\u062a\u06c6\u0631\u06d5 \u062a\u06d5\u0646\u0647\u0627 \u0648\u06d5\u06a9 \u062a\u06c6\u0645\u0627\u0631\u060c \u0628\u06d5\u0628\u06ce \u062f\u06d5\u0633\u062a\u06af\u06d5\u06cc\u0634\u062a\u0646 \u0628\u06c6 \u067e\u06c6\u0631\u062a\u0627\u06b5. \u0647\u06d5\u0698\u0645\u0627\u0631\u06cc \u0686\u0648\u0648\u0646\u06d5\u0698\u0648\u0648\u0631\u06d5\u0648\u06d5 \u062f\u06d5\u062a\u0648\u0627\u0646\u0631\u06ce\u062a \u0647\u06d5\u0631 \u06a9\u0627\u062a\u06ce\u06a9 \u062f\u0648\u0627\u062a\u0631 \u0632\u06cc\u0627\u062f \u0628\u06a9\u0631\u06ce\u062a."},
gajj(){return"\u062f\u06a9\u062a\u06c6\u0631\u0627\u0646\u06cc \u062a\u0631\u06cc \u0626\u06d5\u0645 \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06d5 \u067e\u06ce\u0634\u062a\u0631 \u067e\u06c6\u0631\u062a\u0627\u06b5 \u0628\u06d5\u06a9\u0627\u0631\u062f\u06d5\u0647\u06ce\u0646\u0646 \u2014 \u0628\u0627\u0634\u062a\u0631\u06d5 \u0647\u06d5\u0698\u0645\u0627\u0631\u06ce\u06a9\u06cc\u0634 \u0628\u06c6 \u0626\u06d5\u0645\u06d5 \u0632\u06cc\u0627\u062f \u0628\u06a9\u0631\u06ce\u062a\u060c \u06cc\u0627\u0646 \u062f\u0648\u0627\u062a\u0631 \u06a9\u0627\u062a\u06ce\u06a9 \u067e\u06ce\u0648\u06cc\u0633\u062a\u06cc \u067e\u06ce\u06cc \u0628\u0648\u0648 \u0632\u06cc\u0627\u062f\u06cc \u0628\u06a9\u06d5."},
