ga5g(){return"\u06a9\u06d5\u06cc\u0633 \u062f\u0631\u0648\u0633\u062a \u0646\u0627\u0628\u06ce\u062a \u062a\u0627 \u0633\u06a9\u0627\u0646\u06d5\u0631\u06ce\u06a9\u060c \u06cc\u0627\u0646 \xab\u062f\u06d5\u0631\u06d5\u06a9\u06cc\xbb \u0628\u06c6 \u06a9\u06d5\u06cc\u0633\u06ce\u06a9 \u06a9\u06d5 \u062a\u0627\u0642\u06cc\u06af\u06d5 \u0633\u06a9\u0627\u0646\u06cc \u0646\u06d5\u06a9\u0631\u062f\u0648\u0648\u06d5\u060c \u0647\u06d5\u06b5\u0646\u06d5\u0628\u0698\u06ce\u0631\u062f\u0631\u06ce\u062a."},
ga50(){return"\u062f\u062f\u0627\u0646\u06d5\u06a9\u0627\u0646 \u0628\u06d5 \u067e\u06cc\u062a\u06cc \u0686\u0627\u0631\u06d5\u06a9\u06d5\u06a9\u0627\u0646 \u0644\u06d5 \u0686\u0627\u067e\u062f\u0627 (UL1)"},
ga5_(){return"\u0626\u06d5\u06af\u06d5\u0631 \u06a9\u0627\u0631\u0627 \u0628\u06ce\u062a: \u0644\u06d5\u06cc\u0628\u06b5\u06cc \u06a9\u06d5\u06cc\u0633 \u0648 \u067e\u0633\u0648\u0648\u0644\u06d5\u06cc \u0648\u06d5\u0631\u06af\u0631\u062a\u0646 \u062f\u062f\u0627\u0646\u06d5\u06a9\u0627\u0646 \u0628\u06d5 UL1\u060c UR2\u2026 \u062f\u06d5\u0646\u0648\u0648\u0633\u0646 \u0646\u06d5\u06a9 \u0698\u0645\u0627\u0631\u06d5\u06cc FDI (21\u060c 12\u2026)."},
