ga3W(){return"\u0626\u06d5\u06af\u06d5\u0631 \u06a9\u0627\u0631\u0627 \u0628\u06ce\u062a: \u0644\u06d5\u06cc\u0628\u06b5\u06cc \u06a9\u06d5\u06cc\u0633 \u062f\u06d5\u0628\u06ce\u062a\u06d5 \u0686\u0627\u0631\u06d5\u06a9\u06cc A4 \u0628\u06d5 \u0647\u06d5\u0645\u0627\u0646 \u0642\u06d5\u0628\u0627\u0631\u06d5\u06cc \u0646\u0648\u0648\u0633\u06cc\u0646\u060c \u0626\u06d5\u06af\u06d5\u0631 4 \u0644\u06d5 \u067e\u06d5\u0695\u06d5\u06cc\u06d5\u06a9\u062f\u0627 \u0686\u0627\u067e \u0628\u06a9\u06d5\u06cc\u062a \u0646\u0648\u0648\u0633\u06cc\u0646\u06d5\u06a9\u06d5 \u0628\u06d5 \u0642\u06d5\u0628\u0627\u0631\u06d5\u06cc \u062a\u06d5\u0648\u0627\u0648 \u062f\u06d5\u0631\u062f\u06d5\u0686\u06ce\u062a \u0646\u06d5\u06a9 \u0628\u0686\u0648\u0648\u06a9\u06a9\u0631\u0627\u0648\u06d5. \u0628\u06c6 \u0686\u0627\u067e\u06a9\u06d5\u0631\u06cc \u0644\u06d5\u06cc\u0628\u06b5\u06cc 4\xd76 \u0626\u06cc\u0646\u062c \u06cc\u0634 \u06af\u0648\u0646\u062c\u0627\u0648\u06d5."},
gafq(){return"\u06af\u06c6\u0695\u06cc\u0646\u06cc \u062a\u06d5\u06a9\u0646\u06cc\u0634\u06cc\u0627\u0646\u06cc \u0633\u06a9\u06d5\u0646\u06d5\u0631"},
ganq(){return"\u0632\u06c6\u0631\u062a\u0631\u06cc\u0646 \u06cc\u06d5\u06a9\u06d5 \u0628\u06c6 \u0647\u06d5\u0631 \u06a9\u06d5\u06cc\u0633\u06ce\u06a9 (\u0626\u0627\u0631\u06d5\u0632\u0648\u0648\u0645\u06d5\u0646\u062f\u0627\u0646\u06d5)"},
ganp(){return"\u062a\u06d5\u0646\u0647\u0627 \u0626\u06d5\u0645 \u0698\u0645\u0627\u0631\u06d5\u06cc\u06d5 \u0644\u06d5 \u06cc\u06d5\u06a9\u06d5 \u0628\u06c6 \u0647\u06d5\u0631 \u062f\u0627\u0648\u0627\u06a9\u0627\u0631\u06cc\u06cc\u06d5\u06a9 \u062f\u06d5\u0698\u0645\u06ce\u0631\u062f\u0631\u06ce\u062a\u060c \u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5 5. \u0628\u06d5\u062a\u0627\u06b5\u06cc \u0628\u0647\u06ce\u06b5\u06d5 \u0628\u06c6 \u0628\u06ce \u0633\u0646\u0648\u0648\u0631."},
gao2(){return"\u0646\u0631\u062e\u06cc \u0628\u06d5\u0631\u0632\u062a\u0631 \u062f\u0648\u0627\u06cc (\u06cc\u06d5\u06a9\u06d5 / \u0645\u0627\u0646\u06af)"},
gao4(){return"\u0646\u0631\u062e\u06cc \u0628\u06d5\u0631\u0632\u062a\u0631 \u0628\u06c6 \u0647\u06d5\u0631 \u06cc\u06d5\u06a9\u06d5\u06cc\u06d5\u06a9"},
gao3(){return"\u0626\u0627\u0631\u06d5\u0632\u0648\u0648\u0645\u06d5\u0646\u062f\u0627\u0646\u06d5. \u0626\u06d5\u0648 \u06cc\u06d5\u06a9\u0627\u0646\u06d5\u06cc \u0644\u06d5 \u0645\u0627\u0646\u06af\u06ce\u06a9\u062f\u0627 \u0644\u06d5\u0645 \u0698\u0645\u0627\u0631\u06d5\u06cc\u06d5 \u0632\u06cc\u0627\u062a\u0631 \u062f\u06d5\u0628\u0646 (\u0628\u06d5 \u0695\u06cc\u0632\u0628\u06d5\u0646\u062f\u06cc \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u062f\u0646\u06cc \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627\u0646) \u0628\u06d5 \u0646\u0631\u062e\u06cc \u0628\u06d5\u0631\u0632\u062a\u0631 \u062f\u06d5\u0698\u0645\u06ce\u0631\u062f\u0631\u06ce\u0646\u060c \u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5 600 \u06cc\u06d5\u06a9\u06d5\u06cc \u06cc\u06d5\u06a9\u06d5\u0645 \u0628\u06d5 \u0646\u0631\u062e\u06cc \u0626\u0627\u0633\u0627\u06cc\u06cc\u060c \u067e\u0627\u0634\u0627\u0646 1,500 \u0628\u06c6 \u0647\u06d5\u0631 \u06cc\u06d5\u06a9\u06d5\u06cc\u06d5\u06a9. \u06a9\u0627\u0631\u06cc\u06af\u06d5\u0631\u06cc \u0644\u06d5\u0633\u06d5\u0631 \u0646\u0631\u062e\u06cc \u062a\u0627\u06cc\u0628\u06d5\u062a\u06cc \u06a9\u06d5\u0631\u06d5\u0633\u062a\u06d5\u06a9\u0627\u0646 \u0646\u06cc\u06cc\u06d5. \u0628\u06d5\u062a\u0627\u06b5\u06cc \u0628\u0647\u06ce\u06b5\u06d5 \u0628\u06c6 \u0647\u06cc\u0686."},
ganw(){return"\u0695\u06c6\u0698\u06cc \u0645\u0648\u0648\u0686\u06d5 (\u0626\u0627\u0631\u06d5\u0632\u0648\u0648\u0645\u06d5\u0646\u062f\u0627\u0646\u06d5\u060c 1-28)"},
